cd /workspace/submission && python3 - <<'PYEOF'
import pathlib, ast, sys
for path in sorted(pathlib.Path('.').rglob('*.py')):
    src = path.read_text()
    tree = ast.parse(src)
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                imported.add((a.asname or a.name.split('.')[0]))
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported.add(a.asname or a.name)
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    used |= {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    # module-qualified usage like np.zeros is captured via Name 'np'
    unused = sorted(name for name in imported if name not in used and name != 'annotations')
    if unused:
        print(path, 'unused imports:', unused)
print('scan done')
PYEOF
